TreeNode* current = root;
decLen = 0;
for (int i = 0; i < encLen; ++i) {
    if (encoded[i] == 0) {
        current = current->left;
    } else {
        current = current->right;
    }

    if (current->left == nullptr && current->right == nullptr) {
        decoded[decLen++] = current->data;
        current = root;
    }
}
// END_CODE

